def split_name(full_name):
    """
    Splits a person's full name into a first name and a last name.

    Args:
        full_name (str): The full name of the person.

    Returns:
        tuple: A tuple containing two strings: (first_name, last_name).
               If the full_name is empty or only contains spaces,
               it returns (None, None).
               If the name contains only one word, that word is considered
               the first name and the last name will be an empty string.
    """
    if not full_name or not full_name.strip():
        return (None, None)

    parts = full_name.strip().split()

    if not parts:
        return (None, None)
    elif len(parts) == 1:
        return (parts[0], "")
    else:
        first_name = " ".join(parts[:-1])
        last_name = parts[-1]
        return (first_name, last_name)
